'use strict';
const $ = s => document.querySelector(s);
const KEY='grammys-kitchen-v1';
const RECIPE_COVERS={"original-1":"data:image/jpeg;base64,","original-2":"data:image/jpeg;base64,","recipe-pancakes":"data:image/jpeg;base64,","recipe-sumbitches":"data:image/jpeg;base64,","recipe-anytime-veg-soup":"data:image/jpeg;base64,"};
function coverFor(r){return RECIPE_COVERS[r.id]||r.photo||''}

const seed=[{"id":"original-1","title":"Orange Juice Cookies","category":"Cookies","temperature":"350° (scale not printed)","time":"10 minutes","ingredients":["2 cups sugar","1 cup margarine","2 eggs","1 cup milk","½ can frozen orange juice concentrate, thawed — can size to verify","4½ cups flour","2 teaspoons baking powder","Frosting: a little melted butter (quantity not specified)","Frosting: a little thawed orange juice (quantity not specified)","Frosting: powdered sugar (quantity not specified)"],"steps":["Cream the first three ingredients: sugar, margarine, and eggs.","Add the remaining dough ingredients gradually.","Drop onto cookie sheets.","Bake at 350° for 10 minutes. The printed recipe does not state the temperature scale.","When cool, frost with a little melted butter, a little thawed orange juice, and powdered sugar. Frosting quantities are not specified."],"notes":"1 batch = 100 cookies.","unverified":true,"favorite":false,"photo":"data:image/jpeg;base64,","yield":"","sourceNotes":""},{"id":"original-2","title":"Quick Mix Spritz","category":"Cookies","temperature":"375° (scale not printed)","time":"10–12 minutes","ingredients":["2¼ cups flour","¾ cup sugar","¼ teaspoon baking powder","½ teaspoon salt","1 cup shortening","1 egg","1 tablespoon vanilla","Food coloring (quantity not specified)"],"steps":["Cream shortening, sugar, and egg. The printed directions say “eggs,” while the ingredient list specifies 1 egg.","Gradually add dry ingredients.","When you can form a ball, add food coloring.","Press cookies onto cookie sheet.","Bake at 375° for 10–12 minutes. The printed recipe does not state the temperature scale."],"notes":"","unverified":true,"favorite":false,"photo":"data:image/jpeg;base64,","yield":"5 dozen","sourceNotes":"Vanilla is listed in the ingredients; the printed directions do not say when to add it."},{"id":"recipe-pancakes","title":"Pancakes","category":"Breakfast","yield":"","temperature":"","time":"","ingredients":["1 cup flour","1 cup milk","1 egg","1 teaspoon baking powder","1 teaspoon vanilla","3 tablespoons melted butter","Pinch of sugar"],"steps":["Whisk all ingredients together."],"notes":"When doubling, use 1½ cups flour total instead of 1 cup.","sourceNotes":"The handwritten recipe does not give cooking directions beyond whisking, or specify a cooking time or temperature.","unverified":false,"favorite":false,"photo":"data:image/jpeg;base64,"},{"id":"recipe-sumbitches","title":"Sumbitches","category":"Cookies","yield":"","temperature":"350° (scale not written)","time":"8–9 minutes","ingredients":["½ cup butter","1 cup brown sugar","¾ cup peanut butter","1 egg","1 teaspoon vanilla","1¾ cups flour","½ teaspoon baking soda","¼ teaspoon salt","¾ cup mini chocolate chips","1¼ cups caramel bits"],"steps":["Preheat oven to 350°. Use parchment or grease the pans.","Beat butter and brown sugar until light and fluffy.","Add peanut butter, egg, and vanilla separately.","On low speed, add flour, baking soda, and salt.","Fold in mini chocolate chips and caramel bits.","Place cookies 2 inches apart. Bake for 8–9 minutes."],"notes":"","sourceNotes":"","unverified":false,"favorite":false,"photo":"data:image/jpeg;base64,"},{"id":"recipe-anytime-veg-soup","title":"Anytime Veg Soup","category":"Soups","yield":"","temperature":"","time":"20–30 minutes","ingredients":["½ cup onion, chopped","1 small garlic clove","1 cup celery, chopped","1 cup carrots, chopped","1 cup spinach","½ cup green beans","32 ounces broth","1 can (15 ounces) diced tomatoes","Parsley, basil, and oregano, to taste","Salt and pepper (quantity not specified)"],"steps":["In a soup pot, sauté onion, garlic, celery, carrots, and vegetables; season with salt and pepper.","Add broth, tomatoes, and herbs.","Bring to a boil. Reduce heat to low and simmer for 20–30 minutes."],"notes":"Usually double.\nTurkey is a good addition.\n\nSticky-note adjustments, as written:\nDouble — not celery.\nCelery + carrots 1½ c?\n1 can tomatoes, diced.\n2 broth —\nPeas/carrots (1 bag)\nOnion\nGreen beans (1 bag)\nSpinach (bag)\nTurkey —","sourceNotes":"The question mark and incomplete amounts on the sticky note are preserved in Family notes.","unverified":false,"favorite":false,"photo":"data:image/jpeg;base64,"}];
let selectedCategory='', recipePage=1;
const RECIPES_PER_PAGE=6;
let recipes=structuredClone(seed), onlyFavorites=false, editingId=null, currentId=null, selectedPhoto='', installPrompt;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000)}
function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safePhoto(s){return typeof s==='string' && /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s) && s.length<4000000?s:''}
function validate(data){if(!Array.isArray(data)||data.length>500)throw Error('Choose a valid backup containing up to 500 recipes.');const ids=new Set();return data.map(r=>{if(!r||typeof r.title!=='string'||!r.title.trim()||!Array.isArray(r.ingredients)||!Array.isArray(r.steps))throw Error('The backup contains an invalid recipe.');let id=typeof r.id==='string'?r.id:crypto.randomUUID();if(ids.has(id))throw Error('The backup has duplicate recipe IDs.');ids.add(id);const str=v=>typeof v==='string'?v.slice(0,20000):'';return {id,title:str(r.title).slice(0,120),category:str(r.category).slice(0,60),yield:str(r.yield),temperature:str(r.temperature),time:str(r.time),ingredients:r.ingredients.slice(0,500).map(str),steps:r.steps.slice(0,500).map(str),notes:str(r.notes),sourceNotes:str(r.sourceNotes),unverified:r.unverified!==false,favorite:!!r.favorite,photo:safePhoto(r.photo)}})}
let storageBroken=false;
try{const saved=localStorage.getItem(KEY);if(saved)recipes=validate(JSON.parse(saved))}catch{storageBroken=true;toast('Saved data could not be read. Export a backup before making changes.');}
// Upgrade only unchanged recovery placeholders; preserve edited recipes and their photos.
if (!storageBroken) {
 const upgraded=recipes.map(r=>{
  const original=seed.find(s=>s.id===r.id);
  return original && r.title===`Recipe from original photo · ${r.id==='original-1'?'1':'2'}` && !r.ingredients.length && !r.steps.length && !r.photo ? {...original,favorite:r.favorite} : r;
 });
 if(upgraded.some((r,i)=>r!==recipes[i])) {
  try {localStorage.setItem(KEY,JSON.stringify(upgraded));recipes=upgraded;} catch {toast('Could not update original recipe entries. Export a backup and check storage.');}
 }
}
// Keep handwriting in family notes; preserve any notes the user has edited.
const previousGeneratedNotes={"original-1":"Transcribed from the supplied recipe photo. The handwritten note reads “1 batch = 100 cookies.” The owner clarified that the orange juice amount means half a can of concentrate. Can size remains unspecified; verify it before cooking. The printed temperature has no scale. Frosting amounts are given only as “a little”; powdered sugar has no quantity.","original-2":"Transcribed from the supplied recipe photo. Makes 5 dozen. The ingredient list specifies 1 tablespoon vanilla; the directions do not state when to add it. Verify that step before cooking. The ingredient list says 1 egg; the directions use the plural “eggs.” The printed temperature has no scale. No food coloring amount is specified."};
if(!storageBroken){
 const updated=recipes.map(r=>{
  const original=seed.find(item=>item.id===r.id&&item.title===r.title);if(!original)return r;
  const next={...r};
  if(next.notes===previousGeneratedNotes[r.id]){next.notes=original.notes;next.sourceNotes=original.sourceNotes;}
  if(r.id==='original-1'&&next.yield==='100 cookies per batch (handwritten note)'){
   next.yield='';if(!next.notes.includes('100 cookies'))next.notes+=(next.notes?'\n':'')+'1 batch = 100 cookies.';
  }
  if(next.sourceNotes===undefined)next.sourceNotes=original.sourceNotes;
  return next;
 });
 if(JSON.stringify(updated)!==JSON.stringify(recipes)){try{localStorage.setItem(KEY,JSON.stringify(updated));recipes=updated}catch{toast('Could not save the notes update. Your existing recipes are unchanged.')}}
}
// Add this batch once, preserving existing recipes, favorites, and personal notes.
const HANDWRITTEN_BATCH_KEY='grammys-kitchen-batch-handwritten-2026-11-06';
if(!storageBroken){try{
 if(!localStorage.getItem(HANDWRITTEN_BATCH_KEY)){
  const ids=['recipe-pancakes','recipe-sumbitches','recipe-anytime-veg-soup'];
  const additions=seed.filter(r=>ids.includes(r.id)&&!recipes.some(existing=>existing.id===r.id));
  const next=[...recipes,...additions];
  localStorage.setItem(KEY,JSON.stringify(next));recipes=next;
  localStorage.setItem(HANDWRITTEN_BATCH_KEY,'added');
 }
}catch{toast('Could not save the new recipe batch. Back up your recipes and check device storage.')}}
function persist(next){if(storageBroken){toast('Storage could not be read. Export a backup and clear site data before editing.');return false}try{localStorage.setItem(KEY,JSON.stringify(next));recipes=next;render();return true}catch{toast('Could not save. Device storage may be full or unavailable. Export a backup and try a smaller photo.');return false}}
const COOKBOOK_CATEGORIES=['Breakfast','Cookies','Breads','Cakes','Pies','Desserts','Soups','Casseroles','Main dishes','Side dishes','Salads','Sauces','Drinks','Other'];
function categoryFor(recipe){
 const name=(recipe.category||'Other').trim().replace(/\s+/g,' ')||'Other';
 const aliases={pie:'Pies',pies:'Pies',cake:'Cakes',cakes:'Cakes',cookie:'Cookies',cookies:'Cookies',bread:'Breads',breads:'Breads',soup:'Soups',soups:'Soups',casserole:'Casseroles',casseroles:'Casseroles',salad:'Salads',salads:'Salads',dessert:'Desserts',desserts:'Desserts',sauce:'Sauces',sauces:'Sauces',drink:'Drinks',drinks:'Drinks','main dish':'Main dishes','main dishes':'Main dishes','side dish':'Side dishes','side dishes':'Side dishes'};
 const label=name.toLowerCase();
 const known=aliases[label]||COOKBOOK_CATEGORIES.find(c=>c.toLowerCase()===label);if(known)return known;
 // Broader dish type takes priority over protein in older/imported category labels.
 if(/\bsoups?\b|\bstews?\b/.test(label))return 'Soups';
 if(/\bcasseroles?\b/.test(label))return 'Casseroles';
 if(/\bsalads?\b/.test(label))return 'Salads';
 if(/\bpies?\b/.test(label))return 'Pies';
 if(/\bcakes?\b/.test(label))return 'Cakes';
 if(/\bcookies?\b/.test(label))return 'Cookies';
 if(/\bbreads?\b/.test(label))return 'Breads';
 if(/\bchicken\b|\bpork\b|\bbeef\b|\bfish\b|\bseafood\b|\bturkey\b|\bham\b|\blamb\b|\bvegetarian\b|\bdinner\b|\bentrees?\b/.test(label))return 'Main dishes';
 return 'Other';
}
function categoryGraphic(name){
 const paths={
 'All recipes':'<path d="M4 4h7c1 0 1 1 1 1s0-1 1-1h7v15h-7c-1 0-1 1-1 1s0-1-1-1H4zM12 5v15"/>',
 'Breakfast':'<path d="M3 14h18M5 14a7 7 0 0 1 14 0M12 3v3M4 7l2 2M20 7l-2 2M5 18h14"/>',
 'Cookies':'<path d="M20 12a8 8 0 1 1-8-8 5 5 0 0 0 8 8Z"/><circle cx="9" cy="10" r=".7"/><circle cx="8" cy="15" r=".7"/><circle cx="13" cy="16" r=".7"/>',
 'Breads':'<path d="M5 20V10C1 8 4 3 8 4a6 6 0 0 1 8 0c4-1 7 4 3 6v10ZM9 8v3M15 8v3"/>',
 'Desserts':'<path d="m4 11 16-5v14H4zM4 15h16M15 6V3"/><circle cx="15" cy="3" r="1"/>',
 'Soups':'<path d="M3 12h18a9 9 0 0 1-18 0ZM7 21h10M7 8c-3-2 3-3 0-5M12 8c-3-2 3-3 0-5M17 8c-3-2 3-3 0-5"/>',
 'Casseroles':'<path d="M5 10h14v9H5ZM2 12h3M19 12h3M4 8h16M10 5h4M8 13v3M12 13v3M16 13v3"/>',
 'Main dishes':'<circle cx="12" cy="12" r="6"/><path d="M2 4v6M4 4v6M3 10v10M22 4v16M22 4c-3 2-3 7 0 7"/>',
 'Side dishes':'<path d="M4 12h16a8 8 0 0 1-16 0ZM7 9l2-3M12 9V4M17 9l-2-3M7 21h10"/>',
 'Salads':'<path d="M4 13h16a8 8 0 0 1-16 0ZM12 12C5 12 5 5 5 5s7 0 7 7ZM12 12c0-8 7-8 7-8s1 7-7 8Z"/>',
 'Pies':'<path d="M3 11h18l-3 9H6ZM3 11c0-3 3-5 5-3 2-3 6-3 8 0 2-2 5 0 5 3M8 4l1 2M12 3v3M16 4l-1 2"/>',
 'Cakes':'<path d="M4 11h16v9H4ZM4 15c2 2 3-2 5 0s3-2 5 0 4-2 6 0M7 11V7h10v4M12 7V3"/><path d="M11 3c0-2 2-2 2 0"/>',
 'Sauces':'<path d="M4 11h13v8H4ZM17 12h3c3 0 3 5 0 5h-3M6 7c-2-2 2-2 0-4M11 7c-2-2 2-2 0-4"/>',
 'Drinks':'<path d="M5 8h14l-2 13H7ZM12 8l3-6h4M6 12h12"/>',
 'Other':'<circle cx="6" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="18" cy="12" r="1"/>'};
 return `<svg class="category-graphic" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.Other}</svg>`;
}
function compareListingNames(a,b){return a.localeCompare(b,'en',{sensitivity:'base',numeric:true})}
function render(){
 const categories=[...new Set(recipes.map(categoryFor))].sort(compareListingNames);
 const navScroll=$('#categories').scrollLeft;const favoriteFocused=document.activeElement?.id==='favorites';const focusedCategory=$('#categories').contains(document.activeElement)&&!favoriteFocused?document.activeElement.dataset.category:null;
 const categoryRecipes=onlyFavorites?recipes.filter(r=>r.favorite):recipes;
 const favoriteCount=recipes.filter(r=>r.favorite).length;
 if(selectedCategory&&!categories.includes(selectedCategory))selectedCategory='';
 const allLabel=onlyFavorites?'All favorites':'All recipes';
 const genreButtons=categories.map(c=>`<button type="button" class="category-chip" data-category="${escapeHTML(c)}" aria-pressed="${selectedCategory===c}">${categoryGraphic(c)}<span class="category-name">${escapeHTML(c)}</span><span class="category-count">${categoryRecipes.filter(r=>categoryFor(r)===c).length}</span></button>`).join('');
 $('#categories').innerHTML=`<button type="button" class="category-chip" data-category="" aria-pressed="${!selectedCategory}">${categoryGraphic('All recipes')}<span class="category-name">${allLabel}</span><span class="category-count">${categoryRecipes.length}</span></button><button type="button" id="favorites" class="category-chip favorites-chip" aria-pressed="${onlyFavorites}"><svg class="category-graphic" viewBox="0 0 24 24" aria-hidden="true" fill="${onlyFavorites?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5"><path d="M12 20 4 12C-2 5 7-1 12 6c5-7 14-1 8 6Z"/></svg><span class="category-name">Favorites</span><span class="category-count">${favoriteCount}</span></button>${genreButtons}`;
 $('.section-title h2').textContent=onlyFavorites?'Favorite recipes':'Our family recipes';
 $('#categories').scrollLeft=navScroll;if(favoriteFocused)$('#favorites').focus({preventScroll:true});if(focusedCategory!==null){[...$('#categories').querySelectorAll('button')].find(b=>b.dataset.category===focusedCategory)?.focus({preventScroll:true})}
 const q=$('#search').value.trim().toLowerCase();
 const filtered=recipes.filter(r=>(!onlyFavorites||r.favorite)&&(!selectedCategory||categoryFor(r)===selectedCategory)&&[r.title,r.category,r.notes,...r.ingredients].join(' ').toLowerCase().includes(q)).sort((a,b)=>compareListingNames(a.title.trim(),b.title.trim())||compareListingNames(a.id,b.id));
 const pageCount=Math.max(1,Math.ceil(filtered.length/RECIPES_PER_PAGE));recipePage=Math.min(recipePage,pageCount);
 const offset=(recipePage-1)*RECIPES_PER_PAGE,visible=filtered.slice(offset,offset+RECIPES_PER_PAGE);
 $('#count').textContent=filtered.length>RECIPES_PER_PAGE?`${offset+1}–${offset+visible.length} of ${filtered.length} recipes`:`${filtered.length} ${filtered.length===1?'recipe':'recipes'}`;
 $('#empty').hidden=filtered.length>0;$('#empty').textContent=q?'No matching recipes. Try another search or category.':onlyFavorites?(selectedCategory?`No favorite recipes in ${selectedCategory} yet. Tap a recipe’s heart to save it.`:'No favorites yet. Tap a recipe’s heart to save it here.'):selectedCategory?`No recipes in ${selectedCategory} yet. Add one below.`:'No recipes yet. Add your first recipe below.';
 $('#grid').innerHTML=visible.map(r=>`<article class="card"><div class="card-heading"><h3><button type="button" class="card-link" data-action="open" data-id="${escapeHTML(r.id)}">${escapeHTML(r.title)}</button></h3><button class="favorite" data-action="favorite" data-id="${escapeHTML(r.id)}" aria-label="${r.favorite?'Remove from':'Add to'} favorites: ${escapeHTML(r.title)}" aria-pressed="${r.favorite}" title="${r.favorite?'Saved favorite — click to remove':'Save to favorites'}">${r.favorite?'♥':'♡'}</button></div><div class="card-top">${coverFor(r)?`<img src="${coverFor(r)}" alt="${escapeHTML(r.title)}${RECIPE_COVERS[r.id]?' — illustrative food image':' photo'}" loading="lazy">`:'✧'}</div><div class="card-body"><span class="tag">${escapeHTML(categoryFor(r))}</span><p>${escapeHTML([r.yield.replace(/ per batch \(handwritten note\)/,''),r.time].filter(Boolean).join(' · ')||'A family recipe')}</p></div></article>`).join('');
 $('#pagination').hidden=pageCount<=1;$('#previous-page').disabled=recipePage<=1;$('#next-page').disabled=recipePage>=pageCount;$('#page-position').textContent=`Page ${recipePage} of ${pageCount}`;
 
}
function openRecipe(id){const sameRecipe=currentId===id&&$('#detail').open;const recipeScroll=$('#detail').scrollTop;saveFamilyNotes();const r=recipes.find(r=>r.id===id);if(!r)return;currentId=id;$('#detail-content').innerHTML=`<div class="recipe-sticky"><div><p class="eyebrow">${escapeHTML(categoryFor(r))}</p><h2 id="recipe-title">${escapeHTML(r.title)}</h2></div><div class="recipe-header-actions"><button type="button" class="recipe-favorite" data-detail="favorite" aria-label="${r.favorite?'Remove from':'Add to'} favorites" aria-pressed="${r.favorite}" title="${r.favorite?'Remove from favorites':'Save to favorites'}">${r.favorite?'♥':'♡'}</button><details class="recipe-timer-menu"><summary><span class="timer-menu-label">◷ Timer</span></summary>${timerMarkup(r)}</details><button class="icon close" aria-label="Close recipe">×</button></div></div><p class="muted">${escapeHTML([r.yield,r.temperature,r.time].filter(Boolean).join(' · '))}</p>${coverFor(r)?`<figure class="recipe-cover"><img src="${coverFor(r)}" alt="${escapeHTML(r.title)}${RECIPE_COVERS[r.id]?' — illustrative food image':' photo'}"></figure>`:''}<div class="recipe-columns"><section class="recipe-ingredients"><h3>Ingredients</h3>${renderIngredientSections(r)}</section><section class="recipe-directions"><div class="directions-heading"><h3>Directions</h3><span id="step-progress" role="status"></span><button type="button" class="text" data-reset-checklist hidden>Reset checks</button></div>${renderDirections(r)}</section></div>${r.sourceNotes?`<p class="muted source-note">${escapeHTML(r.sourceNotes)}</p>`:''}<section class="family-notes"><label for="family-notes"><h3>Family notes</h3></label><textarea id="family-notes" data-recipe-id="${escapeHTML(r.id)}" rows="3" placeholder="Add your family notes…">${escapeHTML(r.notes)}</textarea><p id="notes-save-status" class="muted" role="status"></p></section>${RECIPE_COVERS[r.id]?'<p class="muted">Food image is illustrative.</p>':''}<div class="actions"><button data-detail="edit">Edit recipe</button>${r.photo?'<button class="secondary" data-detail="photo">Original recipe photo</button>':''}<button class="secondary" data-detail="print">Print</button><button class="secondary" data-share-recipe>Share</button><button class="text" data-detail="delete">Delete recipe</button></div>`;if(!$('#detail').open)$('#detail').showModal();if(sameRecipe)$('#detail').scrollTop=recipeScroll;else $('#detail').scrollTop=0;paintCookingChecks();tickBakeTimer()}
function openEditor(id=null){editingId=id;const r=recipes.find(r=>r.id===id);const form=$('#recipe-form');form.reset();$('#form-error').textContent='';$('#editor-title').textContent=r?'Edit recipe':'Add a recipe';for(const key of ['title','category','yield','temperature','time','notes'])form.elements[key].value=key==='category'?(r?categoryFor(r):''):(r?.[key]||'');for(const key of ['ingredients','steps'])form.elements[key].value=(r?.[key]||[]).join('\n');selectedPhoto=r?.photo||'';$('#photo-preview').src=selectedPhoto;$('#photo-preview').hidden=!selectedPhoto;$('#editor').showModal();$('#editor').scrollTop=0}
$('#grid').addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const r=recipes.find(r=>r.id===b.dataset.id);if(!r)return;if(b.dataset.action==='open')openRecipe(r.id);else persist(recipes.map(x=>x.id===r.id?{...x,favorite:!x.favorite}:x))});
$('#detail').addEventListener('click',e=>{const action=e.target.closest('[data-detail]')?.dataset.detail;const r=recipes.find(r=>r.id===currentId);if(!action||!r)return;if(action==='edit'){$('#detail').close();openEditor(r.id)}if(action==='favorite'&&persist(recipes.map(x=>x.id===r.id?{...x,favorite:!x.favorite}:x)))openRecipe(r.id);if(action==='photo'&&r.photo){$('#original-photo-content').innerHTML=`<div class="photo-heading"><h2>Original recipe photo</h2><button class="icon close" aria-label="Close original recipe photo">×</button></div><p class="muted">${escapeHTML(r.title)}</p><img class="original-scan" src="${r.photo}" alt="Original recipe photo for ${escapeHTML(r.title)}">`;$('#original-photo').showModal()}if(action==='print')window.print();if(action==='delete'&&confirm(`Delete “${r.title}” from this device? Export a backup first if you want to keep it.`)&&persist(recipes.filter(x=>x.id!==r.id)))$('#detail').close()});
document.addEventListener('click',e=>{if(e.target.closest('.close'))e.target.closest('dialog').close()});
$('#add').onclick=()=>openEditor();$('#search').oninput=()=>{recipePage=1;render()};
$('#categories').onclick=e=>{if(e.target.closest('#favorites')){onlyFavorites=!onlyFavorites;selectedCategory='';recipePage=1;render();scrollToRecipeResults();return}const button=e.target.closest('[data-category]');if(!button)return;selectedCategory=button.dataset.category;recipePage=1;render();scrollToRecipeResults()};
function scrollToRecipeResults(){const nav=$('.browse-nav');const top=$('#grid').getBoundingClientRect().top+window.scrollY-nav.getBoundingClientRect().height-18;window.scrollTo({top:Math.max(0,top),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function changeRecipePage(delta){recipePage+=delta;render();scrollToRecipeResults();$('#page-position').focus({preventScroll:true})}
$('#previous-page').onclick=()=>changeRecipePage(-1);$('#next-page').onclick=()=>changeRecipePage(1);
let photoLoading=false;
$('#photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;photoLoading=true;$('#form-error').textContent='Preparing photo…';try{if(!file.type.startsWith('image/'))throw Error('Please choose an image.');if(file.size>25000000)throw Error('Choose an image smaller than 25 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();selectedPhoto=canvas.toDataURL('image/jpeg',.8);$('#photo-preview').src=selectedPhoto;$('#photo-preview').hidden=false;$('#recipe-form').elements.removePhoto.checked=false;$('#form-error').textContent=''}catch(err){$('#form-error').textContent=err.message||'This image could not be opened. Try a JPEG or PNG.'}finally{photoLoading=false}};
$('#recipe-form').onsubmit=e=>{e.preventDefault();if(photoLoading){$('#form-error').textContent='Please wait for the photo to finish.';return}const f=e.target.elements;const title=f.title.value.trim();if(!title){$('#form-error').textContent='Enter a recipe name.';return}const existing=recipes.find(r=>r.id===editingId);const r={id:editingId||crypto.randomUUID(),title,category:categoryFor({category:f.category.value}),yield:f.yield.value.trim(),temperature:f.temperature.value.trim(),time:f.time.value.trim(),notes:f.notes.value,sourceNotes:existing?.sourceNotes||'',ingredients:f.ingredients.value.split('\n').map(s=>s.trim()).filter(Boolean),steps:f.steps.value.split('\n').map(s=>s.trim()).filter(Boolean),unverified:existing?.unverified??true,favorite:existing?.favorite||false,photo:f.removePhoto.checked?'':selectedPhoto};const next=existing?recipes.map(x=>x.id===editingId?r:x):[...recipes,r];if(persist(next)){$('#editor').close();toast('Recipe saved on this device.');openRecipe(r.id)}else $('#form-error').textContent='Recipe was not saved. Export a backup or try a smaller photo.'};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),recipes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`grammys-kitchen-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup prepared. Keep the downloaded JSON file safe.')};
$('#import').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error('Backup must be smaller than 20 MB.');const data=JSON.parse(await file.text());if(data.version!==1)throw Error('Unsupported backup version.');const next=validate(data.recipes);if(confirm(`Replace the ${recipes.length} recipes on this device with ${next.length} recipes from the backup?`)){if(persist(next))toast('Backup restored.')}}catch(err){toast(err.message||'Unable to restore this backup.')}e.target.value=''};
$('#install').onclick=()=>$('#help').showModal();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#native-install').hidden=false});$('#native-install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('#native-install').hidden=true};
render();
if('serviceWorker' in navigator && location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline setup unavailable. You can still use the cookbook while online.'));

if('serviceWorker' in navigator){let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;if($('#editor').open||bakeTimer?.status==='running'||bakeTimer?.status==='paused'){toast('An update is ready. Finish your current activity, then reopen the cookbook.');return}refreshing=true;location.reload()})}

let familyNotesTimer;
function saveFamilyNotes(){
 clearTimeout(familyNotesTimer);
 const field=$('#family-notes');if(!field)return;
 const recipe=recipes.find(r=>r.id===field.dataset.recipeId);if(!recipe||field.value===recipe.notes)return;
 const saved=persist(recipes.map(r=>r.id===recipe.id?{...r,notes:field.value}:r));
 const status=$('#notes-save-status');if(status)status.textContent=saved?'Saved on this device':'Notes could not be saved. Keep a copy and try again.';
}
$('#detail').addEventListener('input',event=>{if(event.target.id!=='family-notes')return;$('#notes-save-status').textContent='Saving…';clearTimeout(familyNotesTimer);familyNotesTimer=setTimeout(saveFamilyNotes,600)});
$('#detail').addEventListener('change',event=>{if(event.target.id==='family-notes')saveFamilyNotes()});
$('#detail').addEventListener('close',saveFamilyNotes);
